shell_commands:
cat > /tmp/get_ci_failures.mjs << 'EOF'
import fetch from 'node-fetch';

const apiUrl = process.env.LORE_API_URL || 'http://localhost:3000';
const token = process.env.LORE_INGEST_TOKEN;

const response = await fetch(`${apiUrl}/lore_get_ci_failures`, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    ...(token && { Authorization: `Bearer ${token}` }),
  },
  body: JSON.stringify({
    repo: 're-cinq/HALEngine',
    branch: 'loop-bench/37',
  }),
});

const data = await response.text();
console.log(data);
EOF
node /tmp/get_ci_failures.mjs 2>&1 || echo "Failed to fetch CI failures"
